#include <bits/stdc++.h>
using namespace std;

const int MAXN = 305;
const int MAXW = 9 * 300;
const int INF = 1000000007;

static int dp[2][MAXN][MAXW + 1];
static int bestw[MAXW + 1];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    long long T;
    cin >> N >> K >> T;

    vector<int> P(N + 1);
    for (int i = 1; i <= N; i++) cin >> P[i];

    vector<int> s;
    s.reserve(K);

    for (int i = 1; i <= N; i++) {
        int g;
        cin >> g;
        if (g) s.push_back(i);
    }

    int W = 9 * K;

    for (int r = 0; r <= N; r++) {
        fill(dp[0][r], dp[0][r] + W + 1, INF);
        fill(dp[1][r], dp[1][r] + W + 1, INF);
    }

    dp[0][0][0] = 0;

    for (int i = 1; i <= K; i++) {
        int cur = i & 1;
        int prv = (i - 1) & 1;

        for (int r = 0; r <= N; r++) {
            fill(dp[cur][r], dp[cur][r] + W + 1, INF);
        }

        fill(bestw, bestw + W + 1, INF);

        int si = s[i - 1];
        int low = i;
        int high = N - K + i;
        int limitPrev = min(W, 9 * (i - 1));

        for (int j = 1; j <= high; j++) {
            for (int w = 0; w <= limitPrev; w++) {
                bestw[w] = min(bestw[w], dp[prv][j - 1][w]);
            }

            if (j < low) continue;

            int add = abs(si - j);
            int pj = P[j];

            for (int w = 0; w <= limitPrev; w++) {
                if (bestw[w] == INF) continue;

                int nw = w + pj;
                int nc = bestw[w] + add;

                if (nc < dp[cur][j][nw]) {
                    dp[cur][j][nw] = nc;
                }
            }
        }
    }

    int layer = K & 1;
    int ans = 0;

    for (int w = 0; w <= W; w++) {
        int minCost = INF;

        for (int j = 1; j <= N; j++) {
            minCost = min(minCost, dp[layer][j][w]);
        }

        if (minCost <= T) ans = w;
    }

    cout << ans << '\n';

    return 0;
}
